{
  "title": "Does the green button actually boost sales?",
  "setting": "Day 4 at SwiftCart",
  "mission": "Determine if the new checkout button truly increases orders or if it is random chance, and **recommend whether to launch or keep testing**.",
  "deadline": "Product sync with {{lead}} today at 2:00 p.m.",
  "panels": [
    {
      "title": "Checkout test · First 24 hours",
      "metrics": [
        {
          "label": "Blue button (control)",
          "value": "4.1%",
          "note": "41 orders / 1,000 visits"
        },
        {
          "label": "Green button (variant)",
          "value": "4.9%",
          "note": "49 orders / 1,000 visits"
        },
        {
          "label": "Observed gap",
          "value": "+8 orders",
          "note": "+19.5% relative lift"
        }
      ],
      "note": "Traffic split evenly: 1,000 shoppers per version"
    }
  ],
  "team": [
    {
      "id": "lead",
      "role": "Product manager",
      "expertise": "Wants to launch winning features quickly to hit conversion goals.",
      "ai": false
    },
    {
      "id": "marketer",
      "role": "Growth marketer",
      "expertise": "Tracks traffic patterns and worries about wasting marketing budget.",
      "ai": false
    },
    {
      "id": "ai",
      "role": "Analytics assistant",
      "expertise": "Runs hypothesis tests, checks p-values, and calculates sample sizes.",
      "ai": true
    }
  ],
  "meters": [
    {
      "id": "risk",
      "label": "Risk of a false win",
      "start": 60,
      "goodWhen": "low"
    },
    {
      "id": "confidence",
      "label": "{{lead}}'s confidence",
      "start": 50,
      "goodWhen": "high"
    }
  ],
  "skills": [
    {
      "id": "tell-difference",
      "name": "Spotting chance differences",
      "practice": "Check whether an A/B test lift has a p-value below 0.05 before declaring a winner."
    },
    {
      "id": "sample-size",
      "name": "Choosing sample size",
      "practice": "Calculate the sample size required to reliably detect a small percentage shift."
    },
    {
      "id": "explain-result",
      "name": "Explaining data simply",
      "practice": "Explain why an observed lead could just be random noise in two everyday sentences."
    }
  ],
  "startNodeId": "node-1",
  "nodes": [
    {
      "id": "node-1",
      "messages": [
        {
          "from": "lead",
          "text": "Green is up by nearly 20%! Can we roll this out to everyone before lunch?"
        },
        {
          "from": "marketer",
          "text": "Wait, each side only saw 1,000 shoppers. That is only 8 extra orders total. Is that reliable?"
        }
      ],
      "prompt": "What do you do first?",
      "choices": [
        {
          "id": "c1-ship",
          "text": "Roll out the green button to everyone now to capture the 20% conversion lift immediately.",
          "quality": "weak",
          "replies": [
            {
              "from": "lead",
              "text": "Awesome! Flipping the switch across all web traffic now."
            },
            {
              "from": "ai",
              "text": "Warning: With 1,000 visitors per group, an 8-order lead has a 39% chance of being pure luck."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 30
            },
            {
              "meter": "confidence",
              "change": 15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "tell-difference",
              "kind": "improve",
              "text": "You rolled out a variant based on a tiny raw lead without checking if the gap was statistically meaningful.",
              "example": "Ask {{ai}} to run a two-proportion test to see if 8 orders could easily happen by chance."
            }
          ],
          "next": "node-ship-early"
        },
        {
          "id": "c1-ask-ai",
          "text": "Ask {{ai}} to run a hypothesis test to see if an 8-order lead could simply be random chance.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "The p-value is 0.39. If both buttons performed identically, you would see an 8-order gap 39% of the time purely by chance."
            },
            {
              "from": "marketer",
              "text": "A 39% chance of luck? That means this lead is essentially meaningless right now."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -25
            },
            {
              "meter": "confidence",
              "change": 5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "tell-difference",
              "kind": "good",
              "text": "You tested the null hypothesis before celebrating a percentage lift that was mostly random noise.",
              "example": null
            }
          ],
          "next": "node-evaluate"
        },
        {
          "id": "c1-pushback",
          "text": "Tell {{lead}} that 1,000 visitors per version is not enough data and refuse to launch today.",
          "quality": "fair",
          "replies": [
            {
              "from": "lead",
              "text": "Not enough based on what? We need evidence and numbers before we delay our schedule."
            },
            {
              "from": "ai",
              "text": "I can calculate the exact p-value and required sample size whenever you are ready."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -10
            },
            {
              "meter": "confidence",
              "change": -20
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain-result",
              "kind": "improve",
              "text": "You pushed back with your intuition rather than sharing the statistical evidence that {{lead}} needs.",
              "example": "\"Before we launch, let's run a test: 8 extra sales in 1,000 visits often happens purely by luck.\""
            }
          ],
          "next": "node-evaluate"
        }
      ]
    },
    {
      "id": "node-evaluate",
      "messages": [
        {
          "from": "lead",
          "text": "Okay, so 39% probability of luck means we cannot trust this yet. How long do we need to test?"
        },
        {
          "from": "marketer",
          "text": "Can we just check the numbers every morning and call it as soon as green pulls ahead?"
        }
      ],
      "prompt": "How do you decide how much longer to run the test?",
      "choices": [
        {
          "id": "c2-sample-calc",
          "text": "Ask {{ai}} to calculate the exact sample size needed so we know how many days to test.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "To reliably detect a true 0.8% shift, you need ~6,500 visitors per group. At our traffic rate, that is 6 more days."
            },
            {
              "from": "lead",
              "text": "Understood. Let's commit to running the test for a full week without peeking early."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -25
            },
            {
              "meter": "confidence",
              "change": 20
            }
          ],
          "timeJump": {
            "label": "6 days later",
            "panel": {
              "title": "Full week test results",
              "metrics": [
                {
                  "label": "Blue button",
                  "value": "4.2%",
                  "note": "294 orders / 7,000 visits"
                },
                {
                  "label": "Green button",
                  "value": "4.3%",
                  "note": "301 orders / 7,000 visits"
                },
                {
                  "label": "p-value",
                  "value": "0.78",
                  "note": "No significant difference"
                }
              ],
              "note": "Target reached: 14,000 total visitors across 7 days"
            }
          },
          "notes": [
            {
              "skill": "sample-size",
              "kind": "good",
              "text": "You sized the experiment beforehand, which protects against false positives caused by stopping early.",
              "example": null
            }
          ],
          "next": "node-final-call"
        },
        {
          "id": "c2-peek-daily",
          "text": "Check the dashboard each morning and launch green as soon as it takes a 10-order lead.",
          "quality": "weak",
          "replies": [
            {
              "from": "ai",
              "text": "Warning: Peeking repeatedly and stopping on any random fluctuation dramatically increases false positives."
            },
            {
              "from": "marketer",
              "text": "That is like flipping a coin until you get two heads in a row and claiming it always lands on heads."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 25
            },
            {
              "meter": "confidence",
              "change": -5
            }
          ],
          "timeJump": {
            "label": "6 days later",
            "panel": {
              "title": "Full week test results",
              "metrics": [
                {
                  "label": "Blue button",
                  "value": "4.2%",
                  "note": "294 orders / 7,000 visits"
                },
                {
                  "label": "Green button",
                  "value": "4.3%",
                  "note": "301 orders / 7,000 visits"
                },
                {
                  "label": "p-value",
                  "value": "0.78",
                  "note": "No significant difference"
                }
              ],
              "note": "Target reached: 14,000 total visitors across 7 days"
            }
          },
          "notes": [
            {
              "skill": "sample-size",
              "kind": "improve",
              "text": "You suggested peeking and stopping early, which invalidates the statistical test.",
              "example": "Calculate the sample size required up front and wait until reaching that target before judging."
            }
          ],
          "next": "node-final-call"
        },
        {
          "id": "c2-arbitrary-time",
          "text": "Run the test for another full week to cover day-to-day shopping fluctuations across days.",
          "quality": "fair",
          "replies": [
            {
              "from": "lead",
              "text": "A full week makes sense so we capture both weekday and weekend shopping patterns."
            },
            {
              "from": "ai",
              "text": "One week gives us ~7,000 visitors per group, which satisfies the statistical power requirements."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -10
            },
            {
              "meter": "confidence",
              "change": 10
            }
          ],
          "timeJump": {
            "label": "6 days later",
            "panel": {
              "title": "Full week test results",
              "metrics": [
                {
                  "label": "Blue button",
                  "value": "4.2%",
                  "note": "294 orders / 7,000 visits"
                },
                {
                  "label": "Green button",
                  "value": "4.3%",
                  "note": "301 orders / 7,000 visits"
                },
                {
                  "label": "p-value",
                  "value": "0.78",
                  "note": "No significant difference"
                }
              ],
              "note": "Target reached: 14,000 total visitors across 7 days"
            }
          },
          "notes": [
            {
              "skill": "sample-size",
              "kind": "good",
              "text": "Covering a full business cycle ensures weekend shoppers are not missed in your dataset.",
              "example": null
            }
          ],
          "next": "node-final-call"
        }
      ]
    },
    {
      "id": "node-ship-early",
      "messages": [
        {
          "from": "lead",
          "text": "Green has been live for 100% of shoppers for two days, but store conversion slipped to 3.8%."
        },
        {
          "from": "marketer",
          "text": "Did we rush out a button that actually converts worse because we jumped on day one noise?"
        }
      ],
      "prompt": "How do you respond to {{lead}}?",
      "choices": [
        {
          "id": "c2b-revert",
          "text": "Explain that the early 8-order lead was likely noise and recommend switching back to blue.",
          "quality": "strong",
          "replies": [
            {
              "from": "lead",
              "text": "Good catch. Let's revert immediately and calculate our sample size before testing changes again."
            },
            {
              "from": "ai",
              "text": "Reverting stops the conversion leak. We can design a properly powered test next week."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -20
            },
            {
              "meter": "confidence",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "tell-difference",
              "kind": "good",
              "text": "You acknowledged that an unproven early result was random noise and took corrective action.",
              "example": null
            }
          ],
          "next": "ending-reverted"
        },
        {
          "id": "c2b-defend",
          "text": "Advise keeping green live for another month so the store numbers have time to level out.",
          "quality": "weak",
          "replies": [
            {
              "from": "marketer",
              "text": "Keeping an unverified change live while revenue drops is a huge financial risk."
            },
            {
              "from": "lead",
              "text": "I need sound statistical logic, not wishful thinking. We need to be more disciplined."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 25
            },
            {
              "meter": "confidence",
              "change": -30
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain-result",
              "kind": "improve",
              "text": "You recommended sticking with an unverified change instead of investigating whether the original win was real.",
              "example": "\"The early win was within the margin of chance. Let's revert to blue and test systematically.\""
            }
          ],
          "next": "ending-bad-launch"
        }
      ]
    },
    {
      "id": "node-final-call",
      "messages": [
        {
          "from": "lead",
          "text": "The full week test is complete. Green had 7 more orders, but the p-value is 0.78. What do we do?"
        },
        {
          "from": "marketer",
          "text": "Does 7 extra orders out of 7,000 visitors count as a win or not?"
        }
      ],
      "prompt": "How do you explain the final conclusion to {{lead}}?",
      "choices": [
        {
          "id": "c3-clear-explain",
          "text": "Explain in plain words that the high p-value means the 7-order gap is likely pure luck.",
          "quality": "strong",
          "replies": [
            {
              "from": "lead",
              "text": "Got it. So green brings no real benefit. We will keep blue and focus our engineering on new ideas."
            },
            {
              "from": "marketer",
              "text": "Glad we waited for solid numbers instead of wasting time rewriting the checkout code."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -20
            },
            {
              "meter": "confidence",
              "change": 25
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain-result",
              "kind": "good",
              "text": "You explained the p-value in terms of everyday probability without confusing technical jargon.",
              "example": null
            }
          ],
          "next": "ending-solid-decision"
        },
        {
          "id": "c3-jargon",
          "text": "Report that we failed to reject the null hypothesis at the five percent significance level.",
          "quality": "fair",
          "replies": [
            {
              "from": "lead",
              "text": "I do not know what 'reject the null hypothesis' means for our quarterly conversion target."
            },
            {
              "from": "ai",
              "text": "Translation for executive reporting: The green button showed no detectable difference from the blue button."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -5
            },
            {
              "meter": "confidence",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain-result",
              "kind": "improve",
              "text": "You used textbook jargon that left non-technical stakeholders confused about the business outcome.",
              "example": "\"A 7-order gap over 14,000 shoppers is random noise. The new button does not actually improve sales.\""
            }
          ],
          "next": "ending-solid-decision"
        },
        {
          "id": "c3-declare-winner",
          "text": "Declare green the winner because it finished with seven more orders than the blue button.",
          "quality": "weak",
          "replies": [
            {
              "from": "ai",
              "text": "A p-value of 0.78 means identical buttons would produce a difference this big 78% of the time."
            },
            {
              "from": "marketer",
              "text": "If 78% of tests show this gap by pure chance, green did not actually beat blue."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 30
            },
            {
              "meter": "confidence",
              "change": -25
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "tell-difference",
              "kind": "improve",
              "text": "You treated an insignificant difference as a genuine victory, risking poor product changes.",
              "example": "When p-value is 0.78, the observed difference is indistinguishable from random noise."
            }
          ],
          "next": "ending-bad-launch"
        }
      ]
    }
  ],
  "endings": [
    {
      "id": "ending-solid-decision",
      "outcome": "You guided the team to a statistically sound conclusion. SwiftCart kept the blue button, avoiding engineering overhead for an ineffective change."
    },
    {
      "id": "ending-reverted",
      "outcome": "The team reverted the premature launch after conversions lagged. The experience convinced {{lead}} to calculate sample sizes before running future tests."
    },
    {
      "id": "ending-bad-launch",
      "outcome": "SwiftCart deployed a variation that won only due to random noise. Checkout conversion remained flat, and team confidence in testing was shaken."
    }
  ],
  "summary": [
    "A small lead over a small sample often disappears because random noise mimics real improvement.",
    "Calculating sample size in advance prevents stopping tests early on false-positive spikes.",
    "Explaining test results in plain terms helps non-technical partners make sound decisions."
  ]
}

{
  "title": "E se a luz viesse em pacotes visíveis?",
  "setting": "Noite no Museu de Curiosidades",
  "mission": "Investigue uma lanterna misteriosa que não diminui o brilho de forma contínua e **descubra como a luz se comporta em pacotes de energia**.",
  "deadline": null,
  "panels": [
    {
      "title": "Sensor de pacotes de luz",
      "metrics": [
        {
          "label": "Impactos por segundo",
          "value": "1 pacote/s",
          "note": "Pulsos separados"
        },
        {
          "label": "Energia por pulso",
          "value": "1 quantum",
          "note": "Valor indivisível"
        }
      ],
      "note": "Lanterna ajustada na menor intensidade possível."
    }
  ],
  "team": [
    {
      "id": "mediadora",
      "role": "Divulgadora científica",
      "expertise": "Explica fenômenos físicos com analogias visuais do dia a dia",
      "ai": false
    },
    {
      "id": "visitante",
      "role": "Visitante curioso",
      "expertise": "Gosta de fazer testes práticos e mexer em botões",
      "ai": false
    }
  ],
  "meters": [
    {
      "id": "compreensao",
      "label": "Compreensão do fenômeno",
      "start": 50,
      "goodWhen": "high"
    }
  ],
  "skills": [
    {
      "id": "quantizacao",
      "name": "Energia em pacotes",
      "practice": "Explique em uma frase por que atenuar a luz diminui a quantidade de pacotes e não a energia de cada pacote individual."
    },
    {
      "id": "dualidade",
      "name": "Dualidade onda-partícula",
      "practice": "Descreva em uma frase como a luz atinge um alvo como partícula isolada, mas constrói padrões de interferência como onda."
    }
  ],
  "startNodeId": "start",
  "nodes": [
    {
      "id": "start",
      "messages": [
        {
          "from": "mediadora",
          "text": "Esta lanterna especial não enfraquece a luz de modo contínuo. No brilho mínimo, ela dispara pequenos pulsos isolados, como gotas de chuva caindo no sensor."
        },
        {
          "from": "visitante",
          "text": "Será que conseguimos reduzir ainda mais essa luz para obter meio pacote se colocarmos um filtro escuro na frente dela?"
        }
      ],
      "prompt": "O que você decide fazer para testar se o pacote de luz pode ser dividido?",
      "choices": [
        {
          "id": "filtro",
          "text": "Colocar um filtro escuro e observar se os pulsos enfraquecem ou só ficam mais raros.",
          "quality": "strong",
          "replies": [
            {
              "from": "mediadora",
              "text": "Exato! Cada impacto continua marcando um quantum inteiro no detector. O filtro apenas bloqueia pacotes inteiros, reduzindo a frequência dos cliques."
            }
          ],
          "effects": [
            {
              "meter": "compreensao",
              "change": 25
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "quantizacao",
              "kind": "good",
              "text": "Você testou a indivisibilidade do quantum: filtros reduzem a taxa de chegada dos pacotes, não a energia unitária de cada um.",
              "example": null
            }
          ],
          "next": "dupla-fresta"
        },
        {
          "id": "lamina",
          "text": "Posicionar uma lâmina no feixe para tentar partir um pacote de luz pelo meio.",
          "quality": "fair",
          "replies": [
            {
              "from": "visitante",
              "text": "O detector mostra que o pacote bate inteiro à esquerda ou à direita da lâmina. Ele nunca se reparte em duas metades!"
            }
          ],
          "effects": [
            {
              "meter": "compreensao",
              "change": 10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "quantizacao",
              "kind": "good",
              "text": "Você confirmou experimentalmente que o pacote é uma unidade elementar de energia.",
              "example": "Comparar a leitura do sensor com um filtro também ajuda a consolidar essa percepção."
            }
          ],
          "next": "dupla-fresta"
        },
        {
          "id": "dimmer",
          "text": "Girar o botão do dimmer tentando obter uma intensidade menor que um pacote.",
          "quality": "weak",
          "replies": [
            {
              "from": "mediadora",
              "text": "O botão até gira, mas o feixe desliga de repente! A lanterna não consegue emitir uma fração menor que um pacote mínimo de energia."
            }
          ],
          "effects": [
            {
              "meter": "compreensao",
              "change": -15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "quantizacao",
              "kind": "improve",
              "text": "Você tentou buscar uma escala contínua, esquecendo que no mundo quântico a energia só é trocada em múltiplos inteiros de um pacote.",
              "example": "Observe se os impactos chegam como blocos inteiros antes de tentar ajustes intermediários."
            }
          ],
          "next": "dupla-fresta"
        }
      ]
    },
    {
      "id": "dupla-fresta",
      "messages": [
        {
          "from": "visitante",
          "text": "Entendi: a luz viaja em pedacinhos inteiros, como bolinhas de gude! Então já resolvemos o mistério, certo?"
        },
        {
          "from": "mediadora",
          "text": "Ainda falta uma surpresa! Se colocarmos uma placa com duas frestas estreitas na frente desses pacotes, o que veremos acumulado na parede?"
        }
      ],
      "prompt": "Como você conduz o teste da fresta dupla com os pacotes individuais?",
      "choices": [
        {
          "id": "acumular",
          "text": "Deixar os pacotes passarem um a um pelas frestas e observar o padrão acumulado na parede.",
          "quality": "strong",
          "replies": [
            {
              "from": "mediadora",
              "text": "Fenomenal! Cada pacote atinge a tela como um ponto isolado de partícula, mas juntos eles formam franjas de interferência típicas de ondas!"
            }
          ],
          "effects": [
            {
              "meter": "compreensao",
              "change": 25
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "dualidade",
              "kind": "good",
              "text": "Você deixou o padrão estatístico se formar, revelando que a luz se propaga como onda mesmo sendo detectada em pacotes discretos.",
              "example": null
            }
          ],
          "next": "ending-wave-particle"
        },
        {
          "id": "medir-ponto",
          "text": "Focar em um único ponto onde o pacote bateu e tentar medir sua largura na parede.",
          "quality": "fair",
